# ==================== GUARD / NURSE STRESS TEST (COMPLETE) ====================
# CPU-only, Colab-friendly, single-file notebook.
#
# Purpose:
#   Stress-test the GUARD part of the burst system in detail.
#   This code answers:
#     - How accurate is the guard by itself?
#     - How confident is it when right vs wrong?
#     - Is confidence calibrated?
#     - At what thresholds should it trigger the experts?
#     - Which cases are false alarms vs missed hard cases?
#     - What is the full system trade-off if we add a strong expert only on uncertain cases?
#
# Dataset:
#   sklearn digits (balanced, easy + hard samples mixed naturally)
#
# Models:
#   - Guard: smaller RandomForest (the nurse)
#   - Expert: stronger RandomForest (the specialist)
#   - Reference: even stronger model used only for analysis / comparison
#
# Outputs:
#   - Detailed printed report
#   - Threshold sweep table
#   - Confidence bin calibration table
#   - Hard/easy detection table
#   - Example error cases
#   - Optional plots
#
# Notes:
#   - "Hard" is defined operationally as: guard is wrong on that sample.
#   - This is a practical stress test of the guard, not a simulation.

import os
import gc
import math
import time
import warnings
from pathlib import Path

import numpy as np
import pandas as pd
import psutil
import matplotlib.pyplot as plt

from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split
from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import (
    accuracy_score,
    f1_score,
    confusion_matrix,
    classification_report,
    log_loss,
)
from sklearn.preprocessing import label_binarize

warnings.filterwarnings("ignore")

# -----------------------------
# 0) Reproducibility / setup
# -----------------------------
SEED = 42
np.random.seed(SEED)
PROC = psutil.Process(os.getpid())

pd.set_option("display.max_columns", None)
pd.set_option("display.width", 160)
pd.set_option("display.max_rows", 200)

# -----------------------------
# 1) Data
# -----------------------------
print("Loading digits dataset...")
digits = load_digits()
X = digits.data.astype(np.float32)
y = digits.target.astype(np.int64)
class_names = [str(i) for i in sorted(np.unique(y))]

X_trainval, X_test, y_trainval, y_test = train_test_split(
    X, y, test_size=0.20, random_state=SEED, stratify=y
)
X_train, X_val, y_train, y_val = train_test_split(
    X_trainval, y_trainval, test_size=0.25, random_state=SEED, stratify=y_trainval
)

print(f"Dataset ready: {len(X)} samples, {X.shape[1]} features")
print(f"Train={len(X_train)}, Val={len(X_val)}, Test={len(X_test)}")

# -----------------------------
# 2) Models
# -----------------------------
# Guard = the nurse. Smaller, cheaper, always on.
guard = RandomForestClassifier(
    n_estimators=20,
    max_depth=4,
    max_features="sqrt",
    random_state=SEED,
    n_jobs=1,
)

# Specialist expert = stronger doctor.
expert = RandomForestClassifier(
    n_estimators=120,
    max_depth=None,
    max_features="sqrt",
    random_state=SEED + 1,
    n_jobs=1,
)

# Reference = strong model used as a comparison baseline.
reference = RandomForestClassifier(
    n_estimators=160,
    max_depth=None,
    max_features="sqrt",
    random_state=SEED + 2,
    n_jobs=1,
)

print("Training models...")
guard.fit(X_train, y_train)
expert.fit(X_train, y_train)
reference.fit(X_train, y_train)

# -----------------------------
# 3) Core helper functions
# -----------------------------
def model_predict_proba_and_pred(model, X_eval):
    probs = model.predict_proba(X_eval)
    preds = np.argmax(probs, axis=1)
    conf = np.max(probs, axis=1)
    return probs, preds, conf


def expected_calibration_error(confidence, correct, n_bins=10):
    """Simple ECE for multiclass top-1 confidence."""
    confidence = np.asarray(confidence)
    correct = np.asarray(correct).astype(np.float32)
    bins = np.linspace(0.0, 1.0, n_bins + 1)
    ece = 0.0
    rows = []
    for i in range(n_bins):
        lo, hi = bins[i], bins[i + 1]
        if i == n_bins - 1:
            mask = (confidence >= lo) & (confidence <= hi)
        else:
            mask = (confidence >= lo) & (confidence < hi)
        count = int(mask.sum())
        if count == 0:
            rows.append((lo, hi, 0, np.nan, np.nan, np.nan))
            continue
        avg_conf = float(confidence[mask].mean())
        acc = float(correct[mask].mean())
        gap = abs(acc - avg_conf)
        ece += (count / len(confidence)) * gap
        rows.append((lo, hi, count, avg_conf, acc, gap))
    return ece, pd.DataFrame(rows, columns=["bin_low", "bin_high", "count", "avg_conf", "bin_acc", "gap"])


def trigger_metrics(trigger, hard):
    """Treat trigger=True as 'nurse escalates to expert'. hard=True means guard would be wrong."""
    trigger = np.asarray(trigger).astype(bool)
    hard = np.asarray(hard).astype(bool)

    tp = int(np.sum(trigger & hard))
    fp = int(np.sum(trigger & ~hard))
    fn = int(np.sum(~trigger & hard))
    tn = int(np.sum(~trigger & ~hard))

    precision = tp / max(1, tp + fp)
    recall = tp / max(1, tp + fn)
    fpr = fp / max(1, fp + tn)
    fnr = fn / max(1, fn + tp)
    accuracy = (tp + tn) / max(1, len(trigger))

    return {
        "tp": tp,
        "fp": fp,
        "fn": fn,
        "tn": tn,
        "precision": precision,
        "recall": recall,
        "fpr": fpr,
        "fnr": fnr,
        "accuracy": accuracy,
    }


def system_with_threshold(guard_model, expert_model, X_eval, threshold):
    """Guard first. If guard confidence < threshold => trigger expert.\n
    Returns predictions, trigger flags, guard confidence.
    """
    g_probs, g_preds, g_conf = model_predict_proba_and_pred(guard_model, X_eval)
    e_probs, e_preds, e_conf = model_predict_proba_and_pred(expert_model, X_eval)

    trigger = g_conf < threshold
    final_preds = np.where(trigger, e_preds, g_preds)
    return {
        "guard_probs": g_probs,
        "guard_preds": g_preds,
        "guard_conf": g_conf,
        "expert_probs": e_probs,
        "expert_preds": e_preds,
        "expert_conf": e_conf,
        "trigger": trigger,
        "final_preds": final_preds,
    }


def find_top_examples(y_true, pred, conf, n=8, want="wrong"):
    """Return the most interesting cases.
    - want='wrong' -> wrong but overconfident
    - want='right_low' -> correct but low confidence
    """
    y_true = np.asarray(y_true)
    pred = np.asarray(pred)
    conf = np.asarray(conf)
    correct = pred == y_true

    if want == "wrong":
        mask = ~correct
        order = np.argsort(-conf[mask])  # wrong but confident
    else:
        mask = correct
        order = np.argsort(conf[mask])   # right but uncertain

    idxs = np.where(mask)[0][order[:n]]
    rows = []
    for idx in idxs:
        rows.append({
            "index": int(idx),
            "true": int(y_true[idx]),
            "pred": int(pred[idx]),
            "conf": float(conf[idx]),
            "correct": bool(correct[idx]),
        })
    return pd.DataFrame(rows)

# -----------------------------
# 4) Guard stress test on validation and test
# -----------------------------
print("\nRunning guard stress test on TEST set...")

g_probs, g_preds, g_conf = model_predict_proba_and_pred(guard, X_test)
ref_probs, ref_preds, ref_conf = model_predict_proba_and_pred(reference, X_test)
exp_probs, exp_preds, exp_conf = model_predict_proba_and_pred(expert, X_test)

true = y_test.copy()
guard_correct = (g_preds == true)
ref_correct = (ref_preds == true)
expert_correct = (exp_preds == true)

hard_by_guard = ~guard_correct  # operational definition: samples the guard gets wrong

# Basic guard stats
print("\n=== GUARD BASIC STATS ===")
print(f"Guard accuracy           : {accuracy_score(true, g_preds):.4f}")
print(f"Guard macro F1           : {f1_score(true, g_preds, average='macro'):.4f}")
print(f"Guard avg confidence      : {float(g_conf.mean()):.4f}")
print(f"Guard avg conf (correct)  : {float(g_conf[guard_correct].mean()):.4f}")
print(f"Guard avg conf (wrong)    : {float(g_conf[~guard_correct].mean()):.4f}")
print(f"Guard log loss            : {log_loss(true, g_probs, labels=list(range(10))):.4f}")
print(f"Reference accuracy        : {accuracy_score(true, ref_preds):.4f}")
print(f"Expert accuracy           : {accuracy_score(true, exp_preds):.4f}")

# -----------------------------
# 5) Confidence bin calibration
# -----------------------------
print("\n=== CONFIDENCE CALIBRATION ===")
cal_correct = guard_correct.astype(int)
ece, calib_table = expected_calibration_error(g_conf, cal_correct, n_bins=10)
print(f"ECE (expected calibration error): {ece:.4f}")
print(calib_table.round(4).to_string(index=False))

# -----------------------------
# 6) Hard/easy detection meaning
# -----------------------------
# If threshold t means: trigger expert when guard confidence < t.
# Then trigger=True is a guess that the case is hard.
print("\n=== HARD / EASY DETECTION BY THRESHOLD ===")
thresholds = np.round(np.linspace(0.50, 0.99, 20), 2)
rows = []
for t in thresholds:
    trigger = g_conf < t
    m = trigger_metrics(trigger, hard_by_guard)
    # system accuracy if we escalate to expert on triggered cases
    final_preds = np.where(trigger, exp_preds, g_preds)
    sys_acc = accuracy_score(true, final_preds)
    sys_f1 = f1_score(true, final_preds, average='macro')
    rows.append({
        "threshold": float(t),
        "trigger_rate": trigger.mean(),
        "system_accuracy": sys_acc,
        "system_f1": sys_f1,
        "hard_precision": m["precision"],
        "hard_recall": m["recall"],
        "false_trigger_rate": m["fpr"],
        "missed_hard_rate": m["fnr"],
    })
threshold_df = pd.DataFrame(rows)
print(threshold_df.round(4).to_string(index=False))

# Pick a practical threshold for analysis:
# choose the one that maximizes accuracy while keeping trigger rate not too high.
threshold_df["score"] = threshold_df["system_accuracy"] - 0.001 * threshold_df["trigger_rate"]
best_row = threshold_df.sort_values(["score", "system_accuracy"], ascending=False).iloc[0]
best_t = float(best_row["threshold"])
print(f"\nChosen threshold for detailed system analysis: {best_t:.2f}")

# -----------------------------
# 7) Full system analysis at chosen threshold
# -----------------------------
print("\n=== SYSTEM ANALYSIS AT CHOSEN THRESHOLD ===")
sys = system_with_threshold(guard, expert, X_test, best_t)
trigger = sys["trigger"]
final_preds = sys["final_preds"]
final_correct = (final_preds == true)

# How well does the nurse decide when to escalate?
hard_metrics = trigger_metrics(trigger, hard_by_guard)

print(f"Trigger rate                 : {trigger.mean():.4f}")
print(f"Escalation precision (hard)   : {hard_metrics['precision']:.4f}")
print(f"Escalation recall (hard)      : {hard_metrics['recall']:.4f}")
print(f"False alarm rate              : {hard_metrics['fpr']:.4f}")
print(f"Missed-hard rate              : {hard_metrics['fnr']:.4f}")
print(f"System accuracy (guard+expert) : {accuracy_score(true, final_preds):.4f}")
print(f"System macro F1               : {f1_score(true, final_preds, average='macro'):.4f}")

# Compare guard vs system on the cases that were triggered
if trigger.any():
    print(f"Accuracy on triggered cases - guard : {accuracy_score(true[trigger], g_preds[trigger]):.4f}")
    print(f"Accuracy on triggered cases - system: {accuracy_score(true[trigger], final_preds[trigger]):.4f}")
else:
    print("No triggers at this threshold.")

# Compare guard vs system on the easy cases that were NOT triggered
not_trigger = ~trigger
if not_trigger.any():
    print(f"Accuracy on non-triggered cases - guard : {accuracy_score(true[not_trigger], g_preds[not_trigger]):.4f}")
    print(f"Accuracy on non-triggered cases - system: {accuracy_score(true[not_trigger], final_preds[not_trigger]):.4f}")

# -----------------------------
# 8) Operational cost report
# -----------------------------
# A simple CPU-logic proxy:
#   guard cost = 1 unit per sample
#   expert cost = 8 units per sample when triggered
# This is not simulation of the world; it is a transparent accounting model.
guard_cost = 1.0
expert_cost = 8.0
avg_cost_per_sample = guard_cost + trigger.mean() * expert_cost
print("\n=== OPERATIONAL COST ACCOUNTING ===")
print(f"Guard cost per sample (unit)          : {guard_cost:.2f}")
print(f"Expert cost per triggered sample      : {expert_cost:.2f}")
print(f"Average cost per sample at threshold   : {avg_cost_per_sample:.2f}")
print(f"Guard-only cost per sample             : {guard_cost:.2f}")
print(f"Always-expert cost per sample          : {guard_cost + expert_cost:.2f}")

# -----------------------------
# 9) Error case analysis
# -----------------------------
print("\n=== MOST INTERESTING CASES ===")
wrong_confident = find_top_examples(true, g_preds, g_conf, n=10, want="wrong")
right_uncertain = find_top_examples(true, g_preds, g_conf, n=10, want="right_low")
print("\nWrong but overconfident guard predictions:")
print(wrong_confident.to_string(index=False))
print("\nCorrect but uncertain guard predictions:")
print(right_uncertain.to_string(index=False))

# -----------------------------
# 10) Compare guard to reference and expert by difficulty buckets
# -----------------------------
print("\n=== DIFFICULTY BUCKETS (based on guard confidence) ===")
buckets = [0.0, 0.5, 0.6, 0.7, 0.8, 0.9, 1.0]
rows = []
for lo, hi in zip(buckets[:-1], buckets[1:]):
    if hi < 1.0:
        mask = (g_conf >= lo) & (g_conf < hi)
    else:
        mask = (g_conf >= lo) & (g_conf <= hi)
    if mask.sum() == 0:
        continue
    rows.append({
        "conf_bin": f"[{lo:.1f}, {hi:.1f}{')' if hi < 1.0 else ']'}",
        "count": int(mask.sum()),
        "guard_acc": accuracy_score(true[mask], g_preds[mask]),
        "expert_acc": accuracy_score(true[mask], exp_preds[mask]),
        "reference_acc": accuracy_score(true[mask], ref_preds[mask]),
        "avg_conf": float(g_conf[mask].mean()),
    })

bucket_df = pd.DataFrame(rows)
print(bucket_df.round(4).to_string(index=False))

# -----------------------------
# 11) Compact summary table
# -----------------------------
summary = pd.DataFrame([
    {
        "model": "Guard",
        "accuracy": accuracy_score(true, g_preds),
        "macro_f1": f1_score(true, g_preds, average='macro'),
        "log_loss": log_loss(true, g_probs, labels=list(range(10))),
        "avg_conf": float(g_conf.mean()),
        "avg_conf_correct": float(g_conf[guard_correct].mean()),
        "avg_conf_wrong": float(g_conf[~guard_correct].mean()),
    },
    {
        "model": "Expert",
        "accuracy": accuracy_score(true, exp_preds),
        "macro_f1": f1_score(true, exp_preds, average='macro'),
        "log_loss": log_loss(true, exp_probs, labels=list(range(10))),
        "avg_conf": float(exp_conf.mean()),
        "avg_conf_correct": float(exp_conf[expert_correct].mean()),
        "avg_conf_wrong": float(exp_conf[~expert_correct].mean()),
    },
    {
        "model": "Reference",
        "accuracy": accuracy_score(true, ref_preds),
        "macro_f1": f1_score(true, ref_preds, average='macro'),
        "log_loss": log_loss(true, ref_probs, labels=list(range(10))),
        "avg_conf": float(ref_conf.mean()),
        "avg_conf_correct": float(ref_conf[ref_correct].mean()),
        "avg_conf_wrong": float(ref_conf[~ref_correct].mean()),
    },
    {
        "model": f"System@t={best_t:.2f}",
        "accuracy": accuracy_score(true, final_preds),
        "macro_f1": f1_score(true, final_preds, average='macro'),
        "log_loss": np.nan,
        "avg_conf": np.nan,
        "avg_conf_correct": np.nan,
        "avg_conf_wrong": np.nan,
    },
])

print("\n=== SUMMARY TABLE ===")
print(summary.round(4).to_string(index=False))

# -----------------------------
# 12) Optional plots
# -----------------------------
fig, axes = plt.subplots(1, 3, figsize=(18, 4.8))

# Plot 1: confidence histograms
axes[0].hist(g_conf[guard_correct], bins=20, alpha=0.7, label="Guard correct")
axes[0].hist(g_conf[~guard_correct], bins=20, alpha=0.7, label="Guard wrong")
axes[0].set_title("Guard confidence: correct vs wrong")
axes[0].set_xlabel("Confidence")
axes[0].set_ylabel("Count")
axes[0].legend()

# Plot 2: threshold sweep
axes[1].plot(threshold_df["threshold"], threshold_df["system_accuracy"], marker="o", label="System accuracy")
axes[1].plot(threshold_df["threshold"], threshold_df["trigger_rate"], marker="o", label="Trigger rate")
axes[1].set_title("Threshold sweep")
axes[1].set_xlabel("Trigger threshold")
axes[1].legend()

# Plot 3: calibration bins
axes[2].plot(calib_table["avg_conf"], calib_table["bin_acc"], marker="o")
axes[2].plot([0, 1], [0, 1], linestyle="--")
axes[2].set_title("Calibration: confidence vs accuracy")
axes[2].set_xlabel("Avg confidence in bin")
axes[2].set_ylabel("Actual accuracy in bin")

plt.tight_layout()
plt.show()

# -----------------------------
# 13) Save outputs
# -----------------------------
out_dir = Path("/tmp/guard_stress_test_results")
out_dir.mkdir(parents=True, exist_ok=True)
summary.to_csv(out_dir / "summary.csv", index=False)
threshold_df.to_csv(out_dir / "threshold_sweep.csv", index=False)
calib_table.to_csv(out_dir / "calibration_bins.csv", index=False)
bucket_df.to_csv(out_dir / "difficulty_buckets.csv", index=False)
wrong_confident.to_csv(out_dir / "wrong_confident_cases.csv", index=False)
right_uncertain.to_csv(out_dir / "right_uncertain_cases.csv", index=False)

print(f"\nSaved reports to: {out_dir}")
print("Done.")

import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split
from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import accuracy_score, f1_score
from scipy.stats import entropy

# -----------------------------
# 1) Setup & Data
# -----------------------------
SEED = 42
print("Loading Digits Dataset...")
digits = load_digits()
X, y = digits.data, digits.target

X_train, X_test, y_train, y_test = train_test_split(
    X, y, test_size=0.3, random_state=SEED, stratify=y
)

# The "Gold Standard" Expert (The Doctor)
# We keep this fixed to see how different nurses handle it.
expert = RandomForestClassifier(n_estimators=100, random_state=SEED).fit(X_train, y_train)
expert_preds = expert.predict(X_test)
expert_acc = accuracy_score(y_test, expert_preds)

# -----------------------------
# 2) Defining the Nurse Candidates
# -----------------------------
# Strategy A: The "Junior Nurse" (Your v3 - very shallow)
nurse_v3 = RandomForestClassifier(n_estimators=10, max_depth=2, random_state=SEED).fit(X_train, y_train)

# Strategy B: The "Senior Nurse" (Slightly deeper, better knowledge)
nurse_senior = RandomForestClassifier(n_estimators=50, max_depth=7, random_state=SEED).fit(X_train, y_train)

# Strategy C: The "Specialist Nurse" (Standard Depth)
nurse_spec = RandomForestClassifier(n_estimators=50, max_depth=None, random_state=SEED).fit(X_train, y_train)

nurses = {
    "Junior (v3)": nurse_v3,
    "Senior (v4)": nurse_senior,
    "Specialist": nurse_spec
}

# -----------------------------
# 3) The Tournament Logic
# -----------------------------
results = []

print(f"\nExpert Baseline Accuracy: {expert_acc:.4f}")
print("-" * 50)

for name, model in nurses.items():
    # Get probabilities
    probs = model.predict_proba(X_test)
    preds = np.argmax(probs, axis=1)

    # 1. Standard Confidence (Max Prob)
    conf = np.max(probs, axis=1)

    # 2. Entropy (Measurement of "Chaos" in the brain)
    # Higher entropy = more confusion
    ent = entropy(probs.T)

    # Test different trigger thresholds
    for threshold in [0.4, 0.5, 0.6, 0.7, 0.8]:
        # Logic: If confidence is low, call expert
        trigger = conf < threshold
        final_preds = np.where(trigger, expert_preds, preds)

        acc = accuracy_score(y_test, final_preds)
        trigger_rate = np.mean(trigger)

        # Calculate "Efficiency Score"
        # (High accuracy with low trigger rate is the goal)
        efficiency = acc / (1 + trigger_rate)

        results.append({
            "Nurse Type": name,
            "Threshold": threshold,
            "System Acc": acc,
            "Trigger Rate": trigger_rate,
            "Efficiency": efficiency
        })

# -----------------------------
# 4) Leaderboard & Analysis
# -----------------------------
df = pd.DataFrame(results)
leaderboard = df.sort_values(by="System Acc", ascending=False)

print("\n=== THE NURSE LEADERBOARD ===")
print(leaderboard.head(10).to_string(index=False))

# -----------------------------
# 5) Visualizing the Trade-off
# -----------------------------
plt.figure(figsize=(10, 6))
for name in nurses.keys():
    subset = df[df["Nurse Type"] == name]
    plt.plot(subset["Trigger Rate"], subset["System Acc"], marker='o', label=name)

plt.axhline(y=expert_acc, color='r', linestyle='--', label="Always Expert (Baseline)")
plt.title("The Trade-off: Accuracy vs. Trigger Rate (Cost)")
plt.xlabel("Trigger Rate (How often we call the Doctor)")
plt.ylabel("System Accuracy")
plt.legend()
plt.grid(True)
plt.show()

# ==================== GUARD COMPARISON LAB (DIGITS) ====================
# CPU-only, Colab-friendly.
#
# Purpose:
#   Stress-test multiple 'nurse' (guard) strategies before running the full burst system.
#
# What it answers:
#   1) Which guard is most accurate by itself?
#   2) Which guard is best calibrated?
#   3) Which uncertainty signal best detects hard cases?
#      - confidence
#      - entropy
#      - margin (top1 - top2)
#   4) For each guard, what threshold gives the best guard+expert trade-off?
#
# Why this is useful:
#   You do NOT need to rerun the whole system every time.
#   This lab isolates the guard and ranks candidate solutions first.
#
# Dataset:
#   sklearn digits (balanced, has easy + hard samples naturally)
#
# Models:
#   - Junior guard: weak but cheap
#   - Senior guard: stronger
#   - Specialist guard: strongest guard candidate
#   - Calibrated senior: improves confidence quality
#   - Expert: strong specialist used only for final system comparison
#
# Output:
#   - guard-only leaderboard
#   - calibration table (ECE)
#   - hard-case detection table for confidence / entropy / margin
#   - threshold sweeps for guard+expert routing
#   - optional plots

import os
import gc
import math
import time
import warnings
from pathlib import Path

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import psutil

from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split
from sklearn.ensemble import RandomForestClassifier
from sklearn.calibration import CalibratedClassifierCV
from sklearn.metrics import accuracy_score, f1_score, log_loss, roc_auc_score, classification_report

warnings.filterwarnings("ignore")

# -----------------------------
# 0) Setup
# -----------------------------
SEED = 42
np.random.seed(SEED)
PROC = psutil.Process(os.getpid())

pd.set_option("display.max_columns", None)
pd.set_option("display.width", 180)
pd.set_option("display.max_rows", 200)

# -----------------------------
# 1) Data
# -----------------------------
print("Loading digits dataset...")
digits = load_digits()
X = digits.data.astype(np.float32)
y = digits.target.astype(np.int64)

# 60/20/20 split
X_trainval, X_test, y_trainval, y_test = train_test_split(
    X, y, test_size=0.20, random_state=SEED, stratify=y
)
X_train, X_val, y_train, y_val = train_test_split(
    X_trainval, y_trainval, test_size=0.25, random_state=SEED, stratify=y_trainval
)

print(f"Dataset ready: {len(X)} samples, {X.shape[1]} features")
print(f"Train={len(X_train)}, Val={len(X_val)}, Test={len(X_test)}")

# -----------------------------
# 2) Helpers
# -----------------------------
def make_rf(n_estimators, max_depth, random_state, max_features="sqrt"):
    return RandomForestClassifier(
        n_estimators=n_estimators,
        max_depth=max_depth,
        max_features=max_features,
        random_state=random_state,
        n_jobs=1,
    )


def predict_bundle(model, X_eval):
    probs = model.predict_proba(X_eval)
    preds = np.argmax(probs, axis=1)
    conf = np.max(probs, axis=1)
    top2 = np.partition(probs, -2, axis=1)[:, -2:]
    top2_sorted = np.sort(top2, axis=1)
    margin = top2_sorted[:, 1] - top2_sorted[:, 0]  # top1 - top2
    entropy = -np.sum(probs * np.log(probs + 1e-12), axis=1)
    return probs, preds, conf, margin, entropy


def ece_score(confidence, correct, n_bins=10):
    confidence = np.asarray(confidence)
    correct = np.asarray(correct).astype(np.float32)
    bins = np.linspace(0.0, 1.0, n_bins + 1)
    rows = []
    ece = 0.0
    for i in range(n_bins):
        lo, hi = bins[i], bins[i + 1]
        if i == n_bins - 1:
            mask = (confidence >= lo) & (confidence <= hi)
        else:
            mask = (confidence >= lo) & (confidence < hi)
        count = int(mask.sum())
        if count == 0:
            rows.append((lo, hi, 0, np.nan, np.nan, np.nan))
            continue
        avg_conf = float(confidence[mask].mean())
        bin_acc = float(correct[mask].mean())
        gap = abs(bin_acc - avg_conf)
        ece += (count / len(confidence)) * gap
        rows.append((lo, hi, count, avg_conf, bin_acc, gap))
    df = pd.DataFrame(rows, columns=["bin_low", "bin_high", "count", "avg_conf", "bin_acc", "gap"])
    return ece, df


def hard_case_metrics(score, hard, higher_means_harder=True):
    """Treat score as a hardness score.
    If higher_means_harder=True, then larger score => more likely to be hard.
    Returns AUROC and a small confusion summary at median threshold.
    """
    score = np.asarray(score)
    hard = np.asarray(hard).astype(int)

    # AUROC needs both classes
    auc = np.nan
    if len(np.unique(hard)) > 1:
        try:
            auc = roc_auc_score(hard, score if higher_means_harder else -score)
        except Exception:
            auc = np.nan

    thr = float(np.median(score))
    pred_hard = score >= thr if higher_means_harder else score <= thr
    tp = int(np.sum(pred_hard & (hard == 1)))
    fp = int(np.sum(pred_hard & (hard == 0)))
    fn = int(np.sum((~pred_hard) & (hard == 1)))
    tn = int(np.sum((~pred_hard) & (hard == 0)))

    precision = tp / max(1, tp + fp)
    recall = tp / max(1, tp + fn)
    fpr = fp / max(1, fp + tn)

    return {
        "auroc": auc,
        "median_thr": thr,
        "precision": precision,
        "recall": recall,
        "fpr": fpr,
        "tp": tp,
        "fp": fp,
        "fn": fn,
        "tn": tn,
    }


def sweep_thresholds(guard_model, expert_model, X_eval, y_eval, score_kind="confidence", thresholds=None):
    """Guard-only trigger sweep -> final system accuracy after expert escalation.

    score_kind:
      - confidence: trigger when confidence < threshold
      - entropy: trigger when entropy > threshold
      - margin: trigger when margin < threshold
    """
    if thresholds is None:
        if score_kind == "confidence":
            thresholds = np.round(np.linspace(0.20, 0.95, 16), 2)
        elif score_kind == "entropy":
            thresholds = np.round(np.linspace(0.10, 2.20, 16), 2)
        else:  # margin
            thresholds = np.round(np.linspace(0.00, 0.90, 16), 2)

    g_probs, g_preds, g_conf, g_margin, g_entropy = predict_bundle(guard_model, X_eval)
    e_probs, e_preds, e_conf, e_margin, e_entropy = predict_bundle(expert_model, X_eval)
    hard = (g_preds != y_eval)

    rows = []
    for t in thresholds:
        if score_kind == "confidence":
            trigger = g_conf < t
        elif score_kind == "entropy":
            trigger = g_entropy > t
        else:
            trigger = g_margin < t

        final_preds = np.where(trigger, e_preds, g_preds)
        sys_acc = accuracy_score(y_eval, final_preds)
        sys_f1 = f1_score(y_eval, final_preds, average="macro")

        # Trigger quality relative to hard cases (guard misses)
        tp = int(np.sum(trigger & hard))
        fp = int(np.sum(trigger & ~hard))
        fn = int(np.sum((~trigger) & hard))
        tn = int(np.sum((~trigger) & ~hard))
        precision = tp / max(1, tp + fp)
        recall = tp / max(1, tp + fn)
        fpr = fp / max(1, fp + tn)
        fnr = fn / max(1, fn + tp)

        rows.append({
            "threshold": float(t),
            "trigger_rate": float(trigger.mean()),
            "system_accuracy": float(sys_acc),
            "system_f1": float(sys_f1),
            "hard_precision": float(precision),
            "hard_recall": float(recall),
            "false_trigger_rate": float(fpr),
            "missed_hard_rate": float(fnr),
        })

    df = pd.DataFrame(rows)
    return df


def summarize_model(name, model, X_eval, y_eval):
    probs, preds, conf, margin, ent = predict_bundle(model, X_eval)
    correct = (preds == y_eval)
    hard = ~correct
    ece, calib_df = ece_score(conf, correct, n_bins=10)

    # Hard-case detection signals
    conf_hard = hard_case_metrics(1.0 - conf, hard, higher_means_harder=True)
    ent_hard = hard_case_metrics(ent, hard, higher_means_harder=True)
    margin_hard = hard_case_metrics(-margin, hard, higher_means_harder=True)  # smaller margin = harder

    return {
        "name": name,
        "accuracy": accuracy_score(y_eval, preds),
        "macro_f1": f1_score(y_eval, preds, average="macro"),
        "log_loss": log_loss(y_eval, probs, labels=list(range(10))),
        "avg_conf": float(conf.mean()),
        "avg_conf_correct": float(conf[correct].mean()) if np.any(correct) else np.nan,
        "avg_conf_wrong": float(conf[hard].mean()) if np.any(hard) else np.nan,
        "ece": ece,
        "correct": correct,
        "hard": hard,
        "probs": probs,
        "preds": preds,
        "conf": conf,
        "margin": margin,
        "entropy": ent,
        "calib_df": calib_df,
        "conf_hard": conf_hard,
        "ent_hard": ent_hard,
        "margin_hard": margin_hard,
    }

# -----------------------------
# 3) Train candidate guards and expert
# -----------------------------
print("Training candidate guards and expert...")

# Guards
junior = make_rf(n_estimators=10, max_depth=2, random_state=SEED)
senior = make_rf(n_estimators=50, max_depth=7, random_state=SEED + 1)
specialist = make_rf(n_estimators=80, max_depth=None, random_state=SEED + 2)

junior.fit(X_train, y_train)
senior.fit(X_train, y_train)
specialist.fit(X_train, y_train)

# Calibrated version of the senior guard
# Use a fresh base estimator so calibration is done properly.
calibrated_senior = CalibratedClassifierCV(
    estimator=make_rf(n_estimators=50, max_depth=7, random_state=SEED + 1),
    method="isotonic",
    cv=3,
)
calibrated_senior.fit(X_train, y_train)

# Expert used in final routing experiments
expert = make_rf(n_estimators=120, max_depth=None, random_state=SEED + 9)
expert.fit(X_train, y_train)

# -----------------------------
# 4) Guard-only stress test on validation and test
# -----------------------------
models = {
    "Junior": junior,
    "Senior": senior,
    "Specialist": specialist,
    "Calibrated Senior": calibrated_senior,
}

print("\n=== GUARD STRESS TEST: VALIDATION SET ===")
val_rows = []
val_details = {}
for name, model in models.items():
    s = summarize_model(name, model, X_val, y_val)
    val_details[name] = s
    val_rows.append({
        "model": name,
        "accuracy": s["accuracy"],
        "macro_f1": s["macro_f1"],
        "log_loss": s["log_loss"],
        "avg_conf": s["avg_conf"],
        "avg_conf_correct": s["avg_conf_correct"],
        "avg_conf_wrong": s["avg_conf_wrong"],
        "ece": s["ece"],
        "hard_auc_conf": s["conf_hard"]["auroc"],
        "hard_auc_entropy": s["ent_hard"]["auroc"],
        "hard_auc_margin": s["margin_hard"]["auroc"],
    })

val_summary = pd.DataFrame(val_rows).sort_values(["accuracy", "ece"], ascending=[False, True])
print(val_summary.round(4).to_string(index=False))

print("\n=== GUARD STRESS TEST: TEST SET ===")
test_rows = []
test_details = {}
for name, model in models.items():
    s = summarize_model(name, model, X_test, y_test)
    test_details[name] = s
    test_rows.append({
        "model": name,
        "accuracy": s["accuracy"],
        "macro_f1": s["macro_f1"],
        "log_loss": s["log_loss"],
        "avg_conf": s["avg_conf"],
        "avg_conf_correct": s["avg_conf_correct"],
        "avg_conf_wrong": s["avg_conf_wrong"],
        "ece": s["ece"],
        "hard_auc_conf": s["conf_hard"]["auroc"],
        "hard_auc_entropy": s["ent_hard"]["auroc"],
        "hard_auc_margin": s["margin_hard"]["auroc"],
    })

test_summary = pd.DataFrame(test_rows).sort_values(["accuracy", "ece"], ascending=[False, True])
print(test_summary.round(4).to_string(index=False))

# -----------------------------
# 5) Detailed calibration tables for the best guard candidates
# -----------------------------
print("\n=== CALIBRATION TABLES (TEST) ===")
for name in ["Junior", "Senior", "Specialist", "Calibrated Senior"]:
    print(f"\n--- {name} ---")
    calib = test_details[name]["calib_df"]
    print(calib.round(4).to_string(index=False))

# -----------------------------
# 6) Compare uncertainty signals as hard-case detectors
# -----------------------------
print("\n=== HARD-CASE DETECTION LEADERBOARD (TEST) ===")
hard_rows = []
for name in ["Junior", "Senior", "Specialist", "Calibrated Senior"]:
    s = test_details[name]
    hard_rows.append({
        "model": name,
        "hard_auc_conf": s["conf_hard"]["auroc"],
        "hard_auc_entropy": s["ent_hard"]["auroc"],
        "hard_auc_margin": s["margin_hard"]["auroc"],
        "conf_precision": s["conf_hard"]["precision"],
        "conf_recall": s["conf_hard"]["recall"],
        "entropy_precision": s["ent_hard"]["precision"],
        "entropy_recall": s["ent_hard"]["recall"],
        "margin_precision": s["margin_hard"]["precision"],
        "margin_recall": s["margin_hard"]["recall"],
    })
hard_df = pd.DataFrame(hard_rows)
print(hard_df.round(4).to_string(index=False))

# -----------------------------
# 7) Threshold sweeps: if we use each guard in a full guard+expert system
# -----------------------------
print("\n=== GUARD+EXPERT THRESHOLD SWEEPS (TEST) ===")
full_rows = []
for guard_name in ["Junior", "Senior", "Specialist", "Calibrated Senior"]:
    guard_model = models[guard_name]
    for score_kind in ["confidence", "entropy", "margin"]:
        sweep = sweep_thresholds(guard_model, expert, X_test, y_test, score_kind=score_kind)
        # Add a simple score to pick a good operating point:
        # prefer high accuracy with lower trigger rate.
        sweep["score"] = sweep["system_accuracy"] - 0.001 * sweep["trigger_rate"]
        best = sweep.sort_values(["score", "system_accuracy"], ascending=False).iloc[0]
        full_rows.append({
            "guard": guard_name,
            "signal": score_kind,
            "best_threshold": best["threshold"],
            "system_accuracy": best["system_accuracy"],
            "system_f1": best["system_f1"],
            "trigger_rate": best["trigger_rate"],
            "hard_precision": best["hard_precision"],
            "hard_recall": best["hard_recall"],
            "false_trigger_rate": best["false_trigger_rate"],
            "missed_hard_rate": best["missed_hard_rate"],
        })

full_df = pd.DataFrame(full_rows).sort_values(["system_accuracy", "trigger_rate"], ascending=[False, True])
print(full_df.round(4).to_string(index=False))

# -----------------------------
# 8) A quick comparison of final system outputs for the best variants
# -----------------------------
# Pick the best guard+signal combo from the table above.
best_combo = full_df.iloc[0]
print("\nBest observed guard+expert combo:")
print(best_combo.to_string())

# Build and evaluate the chosen combo on the test set.
chosen_guard = models[best_combo["guard"]]
chosen_signal = best_combo["signal"]
chosen_threshold = float(best_combo["best_threshold"])

chosen_probs, chosen_preds, chosen_conf, chosen_margin, chosen_entropy = predict_bundle(chosen_guard, X_test)
expert_probs, expert_preds, expert_conf, expert_margin, expert_entropy = predict_bundle(expert, X_test)

if chosen_signal == "confidence":
    trigger = chosen_conf < chosen_threshold
elif chosen_signal == "entropy":
    trigger = chosen_entropy > chosen_threshold
else:
    trigger = chosen_margin < chosen_threshold

final_preds = np.where(trigger, expert_preds, chosen_preds)
print("\n=== CHOSEN SYSTEM ON TEST ===")
print(f"Guard used            : {best_combo['guard']}")
print(f"Signal used           : {chosen_signal}")
print(f"Threshold             : {chosen_threshold:.4f}")
print(f"Trigger rate          : {trigger.mean():.4f}")
print(f"Final system accuracy : {accuracy_score(y_test, final_preds):.4f}")
print(f"Final system macro F1  : {f1_score(y_test, final_preds, average='macro'):.4f}")
print(f"Guard-only accuracy    : {accuracy_score(y_test, chosen_preds):.4f}")
print(f"Expert accuracy        : {accuracy_score(y_test, expert_preds):.4f}")

# -----------------------------
# 9) Quick lists of interesting examples
# -----------------------------
def example_table(y_true, preds, conf, title, want="wrong", n=10):
    y_true = np.asarray(y_true)
    preds = np.asarray(preds)
    conf = np.asarray(conf)
    correct = preds == y_true
    if want == "wrong":
        mask = ~correct
        order = np.argsort(-conf[mask])
    else:
        mask = correct
        order = np.argsort(conf[mask])
    idxs = np.where(mask)[0][order[:n]]
    rows = []
    for idx in idxs:
        rows.append({
            "index": int(idx),
            "true": int(y_true[idx]),
            "pred": int(preds[idx]),
            "conf": float(conf[idx]),
            "correct": bool(correct[idx]),
        })
    df = pd.DataFrame(rows)
    print(f"\n{title}")
    print(df.to_string(index=False))
    return df

wrong_overconf = example_table(y_test, test_details["Senior"]["preds"], test_details["Senior"]["conf"], "Senior: wrong but confident", want="wrong", n=10)
right_uncertain = example_table(y_test, test_details["Senior"]["preds"], test_details["Senior"]["conf"], "Senior: right but uncertain", want="right_low", n=10)

# -----------------------------
