axes[0].set_xlabel("Confidence")
axes[0].set_ylabel("Count")
axes[0].legend()

# Plot B: threshold sweep for Senior-confidence
sweep = sweep_thresholds(models["Senior"], expert, X_test, y_test, score_kind="confidence")
axes[1].plot(sweep["threshold"], sweep["system_accuracy"], marker="o", label="System accuracy")
axes[1].plot(sweep["threshold"], sweep["trigger_rate"], marker="o", label="Trigger rate")
axes[1].set_title("Senior + expert sweep")
axes[1].set_xlabel("Confidence threshold")
axes[1].legend()

# Plot C: calibration curve for Senior vs Calibrated Senior
sen_cal = test_details["Senior"]["calib_df"]
cal_cal = test_details["Calibrated Senior"]["calib_df"]
axes[2].plot(sen_cal["avg_conf"], sen_cal["bin_acc"], marker="o", label="Senior")
axes[2].plot(cal_cal["avg_conf"], cal_cal["bin_acc"], marker="o", label="Calibrated Senior")
