# ==================== BALANCED GUARD STRESS LAB (REPRODUCIBLE) ====================
# CPU-only, Colab-friendly, single-file notebook.
#
# What this notebook does:
#   1) Uses a real binary dataset balanced to 50/50.
#   2) Repeats the experiment across multiple random seeds.
#   3) Compares several guard (nurse) strategies:
#        - Junior
#        - Senior
#        - Specialist
#        - Calibrated Senior
#   4) Stress-tests multiple uncertainty signals:
#        - confidence (low confidence => hard)
#        - entropy (high entropy => hard)
#        - margin (small top1-top2 margin => hard)
#        - combo (weighted blend of all three)
#   5) Sweeps thresholds on validation only, then reports test results.
#   6) Adds an oracle ceiling (perfect hard-case routing) for context.
#   7) Aggregates mean/std over seeds so the result is reproducible and less noisy.
#
# Why this is useful:
#   It isolates the 'nurse' and tests it fairly before you commit to a full system.
#   This is not a simulation of the world; it is a real repeated benchmark.
#
# Dataset:
#   sklearn breast cancer dataset, balanced to 50/50 by downsampling the majority class.
#   This gives a real binary task with a fair class balance.
#
# Output:
#   - Per-seed reports
#   - Guard leaderboard (accuracy, ECE, hard-case AUC)
#   - Full routing leaderboard (best threshold selected on validation)
#   - Oracle routing ceiling
#   - Aggregate mean/std tables
#   - CSV files saved locally

import gc
import math
import warnings
from pathlib import Path

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import psutil

from sklearn.datasets import load_breast_cancer
from sklearn.model_selection import train_test_split
from sklearn.ensemble import RandomForestClassifier, ExtraTreesClassifier
from sklearn.calibration import CalibratedClassifierCV
from sklearn.metrics import accuracy_score, f1_score, log_loss, roc_auc_score
from sklearn.base import clone

warnings.filterwarnings("ignore")

# -----------------------------
# 0) Global config
# -----------------------------
GLOBAL_SEED = 42
SEEDS = [11, 22, 33, 44, 55]
COST_PENALTY = 0.002  # higher => prefer fewer expert calls
N_BINS = 10
OUT_DIR = Path("/tmp/balanced_guard_stress_lab_results")
OUT_DIR.mkdir(parents=True, exist_ok=True)

np.random.seed(GLOBAL_SEED)
PROC = psutil.Process()

pd.set_option("display.max_columns", None)
pd.set_option("display.width", 180)
pd.set_option("display.max_rows", 250)

# -----------------------------
# 1) Dataset: real + balanced 50/50
# -----------------------------
def load_balanced_breast_cancer(seed: int = 42):
    data = load_breast_cancer()
    X = data.data.astype(np.float32)
    y = data.target.astype(np.int64)

    # The original dataset is not 50/50. Downsample the majority class so the
    # benchmark is fair and symmetric.
    idx0 = np.where(y == 0)[0]
    idx1 = np.where(y == 1)[0]
    n = min(len(idx0), len(idx1))

    rng = np.random.default_rng(seed)
    sel0 = rng.choice(idx0, size=n, replace=False)
    sel1 = rng.choice(idx1, size=n, replace=False)
    idx = np.concatenate([sel0, sel1])
    rng.shuffle(idx)

    return X[idx], y[idx], data.feature_names


X_ALL, Y_ALL, FEATURE_NAMES = load_balanced_breast_cancer(GLOBAL_SEED)
print("Loaded balanced breast cancer dataset")
print(f"Total samples: {len(X_ALL)} | Features: {X_ALL.shape[1]}")
print(f"Class balance: {np.bincount(Y_ALL).tolist()} (target is now 50/50)")

# -----------------------------
# 2) Model builders
# -----------------------------
def make_rf(n_estimators: int, max_depth, random_state: int, max_features="sqrt"):
    return RandomForestClassifier(
        n_estimators=n_estimators,
        max_depth=max_depth,
        max_features=max_features,
        random_state=random_state,
        n_jobs=1,
    )


def make_calibrated_guard(base_model):
    # sklearn API changed over time; support both forms.
    try:
        return CalibratedClassifierCV(estimator=clone(base_model), method="isotonic", cv=3)
    except TypeError:
        return CalibratedClassifierCV(base_estimator=clone(base_model), method="isotonic", cv=3)


# -----------------------------
# 3) Prediction / uncertainty helpers
# -----------------------------
def bundle_predictions(model, X_eval):
    probs = model.predict_proba(X_eval)
    preds = np.argmax(probs, axis=1)
    conf = np.max(probs, axis=1)

    # Binary or multiclass: top1-top2 margin
    top2 = np.partition(probs, -2, axis=1)[:, -2:]
    top2_sorted = np.sort(top2, axis=1)
    margin = top2_sorted[:, 1] - top2_sorted[:, 0]

    entropy = -np.sum(probs * np.log(probs + 1e-12), axis=1)
    return probs, preds, conf, margin, entropy


def minmax_fit(x):
    x = np.asarray(x, dtype=np.float64)
    return float(np.min(x)), float(np.max(x))


def minmax_transform(x, lo, hi):
    x = np.asarray(x, dtype=np.float64)
    denom = hi - lo
    if abs(denom) < 1e-12:
        return np.zeros_like(x, dtype=np.float64)
    out = (x - lo) / denom
    return np.clip(out, 0.0, 1.0)


def expected_calibration_error(confidence, correct, n_bins=10):
    confidence = np.asarray(confidence, dtype=np.float64)
    correct = np.asarray(correct, dtype=np.float64)
    bins = np.linspace(0.0, 1.0, n_bins + 1)

    rows = []
    ece = 0.0
    for i in range(n_bins):
        lo, hi = bins[i], bins[i + 1]
        if i == n_bins - 1:
            mask = (confidence >= lo) & (confidence <= hi)
        else:
            mask = (confidence >= lo) & (confidence < hi)

        count = int(mask.sum())
        if count == 0:
            rows.append((lo, hi, 0, np.nan, np.nan, np.nan))
            continue

        avg_conf = float(confidence[mask].mean())
        bin_acc = float(correct[mask].mean())
        gap = abs(bin_acc - avg_conf)
        ece += (count / len(confidence)) * gap
        rows.append((lo, hi, count, avg_conf, bin_acc, gap))

    table = pd.DataFrame(rows, columns=["bin_low", "bin_high", "count", "avg_conf", "bin_acc", "gap"])
    return ece, table


def hard_case_metrics(score, hard, higher_means_harder=True):
    """Treat score as a hardness score and compare it to hard = guard wrong."""
    score = np.asarray(score, dtype=np.float64)
    hard = np.asarray(hard).astype(bool)

    auc = np.nan
    if len(np.unique(hard)) > 1:
        try:
            auc = roc_auc_score(hard.astype(int), score if higher_means_harder else -score)
        except Exception:
            auc = np.nan

    thr = float(np.median(score))
    pred_hard = score >= thr if higher_means_harder else score <= thr

    tp = int(np.sum(pred_hard & hard))
    fp = int(np.sum(pred_hard & ~hard))
    fn = int(np.sum((~pred_hard) & hard))
    tn = int(np.sum((~pred_hard) & ~hard))

    precision = tp / max(1, tp + fp)
    recall = tp / max(1, tp + fn)
    fpr = fp / max(1, fp + tn)
    fnr = fn / max(1, fn + tp)

    return {
        "auroc": auc,
        "median_thr": thr,
        "precision": precision,
        "recall": recall,
        "fpr": fpr,
        "fnr": fnr,
        "tp": tp,
        "fp": fp,
        "fn": fn,
        "tn": tn,
    }


def make_hard_scores(conf, margin, entropy, stats=None):
    """Higher score => harder case.

    stats is a dict of fit ranges from validation:
      {
        'conf_lo': ..., 'conf_hi': ...,
        'margin_lo': ..., 'margin_hi': ...,
        'ent_lo': ..., 'ent_hi': ...
      }
    If stats is None, fit on the passed arrays.
    """
    conf = np.asarray(conf, dtype=np.float64)
    margin = np.asarray(margin, dtype=np.float64)
    entropy = np.asarray(entropy, dtype=np.float64)

    if stats is None:
        stats = {
            "conf_lo": float(np.min(conf)),
            "conf_hi": float(np.max(conf)),
            "margin_lo": float(np.min(margin)),
            "margin_hi": float(np.max(margin)),
            "ent_lo": float(np.min(entropy)),
            "ent_hi": float(np.max(entropy)),
        }

    # Higher hardness = lower confidence, lower margin, higher entropy.
    conf_hard = 1.0 - minmax_transform(conf, stats["conf_lo"], stats["conf_hi"])
    margin_hard = 1.0 - minmax_transform(margin, stats["margin_lo"], stats["margin_hi"])
    ent_hard = minmax_transform(entropy, stats["ent_lo"], stats["ent_hi"])

    # Weighted blend: a practical future idea.
    combo = 0.45 * conf_hard + 0.25 * margin_hard + 0.30 * ent_hard

    return {
        "confidence_hard": conf_hard,
        "margin_hard": margin_hard,
        "entropy_hard": ent_hard,
        "combo_hard": combo,
        "fit_stats": stats,
    }


def sweep_thresholds(y_true, guard_preds, expert_preds, hard_score, hard_label, score_name, thresholds=None):
    """Evaluate a routing rule on a validation or test set.

    trigger = hard_score > threshold
    (higher score means more uncertain / harder)
    """
    hard_score = np.asarray(hard_score, dtype=np.float64)
    y_true = np.asarray(y_true)
    guard_preds = np.asarray(guard_preds)
    expert_preds = np.asarray(expert_preds)
    hard_label = np.asarray(hard_label).astype(bool)

    if thresholds is None:
        thresholds = np.unique(np.quantile(hard_score, np.linspace(0.05, 0.95, 25)))

    rows = []
    for t in thresholds:
        trigger = hard_score > t
        final_preds = np.where(trigger, expert_preds, guard_preds)
        sys_acc = accuracy_score(y_true, final_preds)
        sys_f1 = f1_score(y_true, final_preds, average="binary")

        tp = int(np.sum(trigger & hard_label))
        fp = int(np.sum(trigger & ~hard_label))
        fn = int(np.sum((~trigger) & hard_label))
        tn = int(np.sum((~trigger) & ~hard_label))

        hard_precision = tp / max(1, tp + fp)
        hard_recall = tp / max(1, tp + fn)
        false_trigger_rate = fp / max(1, fp + tn)
        missed_hard_rate = fn / max(1, fn + tp)

        rows.append({
            "signal": score_name,
            "threshold": float(t),
            "trigger_rate": float(trigger.mean()),
            "system_accuracy": float(sys_acc),
            "system_f1": float(sys_f1),
            "hard_precision": float(hard_precision),
            "hard_recall": float(hard_recall),
            "false_trigger_rate": float(false_trigger_rate),
            "missed_hard_rate": float(missed_hard_rate),
        })

    return pd.DataFrame(rows)


def summarize_guard(name, model, X_eval, y_eval):
    probs, preds, conf, margin, entropy = bundle_predictions(model, X_eval)
    correct = preds == y_eval
    hard = ~correct
    ece, calib_table = expected_calibration_error(conf, correct, n_bins=N_BINS)

    hard_conf = hard_case_metrics(1.0 - conf, hard, higher_means_harder=True)
    hard_margin = hard_case_metrics(-margin, hard, higher_means_harder=True)
    hard_entropy = hard_case_metrics(entropy, hard, higher_means_harder=True)

    return {
        "name": name,
        "accuracy": accuracy_score(y_eval, preds),
        "macro_f1": f1_score(y_eval, preds, average="binary"),
        "log_loss": log_loss(y_eval, probs, labels=[0, 1]),
        "avg_conf": float(conf.mean()),
        "avg_conf_correct": float(conf[correct].mean()) if np.any(correct) else np.nan,
        "avg_conf_wrong": float(conf[hard].mean()) if np.any(hard) else np.nan,
        "ece": ece,
        "preds": preds,
        "probs": probs,
        "conf": conf,
        "margin": margin,
        "entropy": entropy,
        "correct": correct,
        "hard": hard,
        "calib_table": calib_table,
        "hard_conf": hard_conf,
        "hard_margin": hard_margin,
        "hard_entropy": hard_entropy,
    }


def pick_best_threshold_on_val(y_val, guard_preds_val, expert_preds_val, hard_scores_val, hard_label_val, signal_name, lambda_cost=COST_PENALTY):
    sweep = sweep_thresholds(
        y_true=y_val,
        guard_preds=guard_preds_val,
        expert_preds=expert_preds_val,
        hard_score=hard_scores_val,
        hard_label=hard_label_val,
        score_name=signal_name,
    )
    sweep["score"] = sweep["system_accuracy"] - lambda_cost * sweep["trigger_rate"]
    best = sweep.sort_values(["score", "system_accuracy"], ascending=[False, False]).iloc[0]
    return sweep, best


def choose_guard_and_signal_for_seed(seed, X_train, y_train, X_val, y_val, X_test, y_test):
    """Train models, choose best guard/signal on validation, then evaluate on test."""
    # Candidate guards
    junior = make_rf(n_estimators=20, max_depth=3, random_state=seed)
    senior = make_rf(n_estimators=80, max_depth=6, random_state=seed + 1)
    specialist = ExtraTreesClassifier(
        n_estimators=120,
        max_depth=None,
        max_features="sqrt",
        random_state=seed + 2,
        n_jobs=1,
    )

    junior.fit(X_train, y_train)
    senior.fit(X_train, y_train)
    specialist.fit(X_train, y_train)

    calibrated_senior = make_calibrated_guard(make_rf(n_estimators=80, max_depth=6, random_state=seed + 1))
    calibrated_senior.fit(X_train, y_train)

    expert = make_rf(n_estimators=160, max_depth=None, random_state=seed + 9)
    reference = make_rf(n_estimators=220, max_depth=None, random_state=seed + 19)
    expert.fit(X_train, y_train)
    reference.fit(X_train, y_train)

    guards = {
        "Junior": junior,
        "Senior": senior,
        "Specialist": specialist,
        "Calibrated Senior": calibrated_senior,
    }

    # Bundle test / val predictions for guard candidates and experts.
    expert_probs_val, expert_preds_val, expert_conf_val, expert_margin_val, expert_entropy_val = bundle_predictions(expert, X_val)
    expert_probs_test, expert_preds_test, expert_conf_test, expert_margin_test, expert_entropy_test = bundle_predictions(expert, X_test)
    ref_probs_test, ref_preds_test, ref_conf_test, ref_margin_test, ref_entropy_test = bundle_predictions(reference, X_test)

    # -------------------------
    # Guard-only summaries
    # -------------------------
    guard_val_rows = []
    guard_test_rows = []
    guard_detail = {}
    for gname, gmodel in guards.items():
        val_sum = summarize_guard(gname, gmodel, X_val, y_val)
        test_sum = summarize_guard(gname, gmodel, X_test, y_test)
        guard_detail[gname] = {
            "val": val_sum,
            "test": test_sum,
        }
        guard_val_rows.append({
            "seed": seed,
            "model": gname,
            "accuracy": val_sum["accuracy"],
            "macro_f1": val_sum["macro_f1"],
            "log_loss": val_sum["log_loss"],
            "avg_conf": val_sum["avg_conf"],
            "avg_conf_correct": val_sum["avg_conf_correct"],
            "avg_conf_wrong": val_sum["avg_conf_wrong"],
            "ece": val_sum["ece"],
            "hard_auc_conf": val_sum["hard_conf"]["auroc"],
            "hard_auc_margin": val_sum["hard_margin"]["auroc"],
            "hard_auc_entropy": val_sum["hard_entropy"]["auroc"],
        })
        guard_test_rows.append({
            "seed": seed,
            "model": gname,
            "accuracy": test_sum["accuracy"],
            "macro_f1": test_sum["macro_f1"],
            "log_loss": test_sum["log_loss"],
            "avg_conf": test_sum["avg_conf"],
            "avg_conf_correct": test_sum["avg_conf_correct"],
            "avg_conf_wrong": test_sum["avg_conf_wrong"],
            "ece": test_sum["ece"],
            "hard_auc_conf": test_sum["hard_conf"]["auroc"],
            "hard_auc_margin": test_sum["hard_margin"]["auroc"],
            "hard_auc_entropy": test_sum["hard_entropy"]["auroc"],
        })

    guard_val_df = pd.DataFrame(guard_val_rows)
    guard_test_df = pd.DataFrame(guard_test_rows)

    # -------------------------
    # Validation-based thresholds and final test evaluation
    # -------------------------
    route_rows = []
    route_detail = []

    for gname, gmodel in guards.items():
        # Val / test bundles for guard
        g_probs_val, g_preds_val, g_conf_val, g_margin_val, g_entropy_val = bundle_predictions(gmodel, X_val)
        g_probs_test, g_preds_test, g_conf_test, g_margin_test, g_entropy_test = bundle_predictions(gmodel, X_test)

        hard_val = g_preds_val != y_val
        hard_test = g_preds_test != y_test

        # Fit normalization stats on validation only, then apply to test.
        stats = {
            "conf_lo": float(np.min(g_conf_val)),
            "conf_hi": float(np.max(g_conf_val)),
            "margin_lo": float(np.min(g_margin_val)),
            "margin_hi": float(np.max(g_margin_val)),
            "ent_lo": float(np.min(g_entropy_val)),
            "ent_hi": float(np.max(g_entropy_val)),
        }

        val_scores = make_hard_scores(g_conf_val, g_margin_val, g_entropy_val, stats=stats)
        test_scores = make_hard_scores(g_conf_test, g_margin_test, g_entropy_test, stats=stats)

        signal_maps = {
            "confidence": val_scores["confidence_hard"],
            "entropy": val_scores["entropy_hard"],
            "margin": val_scores["margin_hard"],
            "combo": val_scores["combo_hard"],
        }
        signal_maps_test = {
            "confidence": test_scores["confidence_hard"],
            "entropy": test_scores["entropy_hard"],
            "margin": test_scores["margin_hard"],
            "combo": test_scores["combo_hard"],
        }

        # Also store hard-case AUCs for the guard on validation (diagnostic)
        hard_auc_row = {
            "seed": seed,
            "model": gname,
            "val_hard_auc_conf": val_sum_for(guard_detail[gname]["val"], "hard_conf"),
            "val_hard_auc_margin": val_sum_for(guard_detail[gname]["val"], "hard_margin"),
            "val_hard_auc_entropy": val_sum_for(guard_detail[gname]["val"], "hard_entropy"),
        }

        # Threshold sweep on validation, then evaluate the chosen threshold on test.
        for signal_name, hard_score_val in signal_maps.items():
            sweep, best = pick_best_threshold_on_val(
                y_val=y_val,
                guard_preds_val=g_preds_val,
                expert_preds_val=expert_preds_val,
                hard_scores_val=hard_score_val,
                hard_label_val=hard_val,
                signal_name=signal_name,
            )
            chosen_t = float(best["threshold"])

            hard_score_test = signal_maps_test[signal_name]
            trigger_test = hard_score_test > chosen_t
            final_preds_test = np.where(trigger_test, expert_preds_test, g_preds_test)

            # Diagnostic: the perfect routing ceiling if we could trigger exactly on guard mistakes.
            oracle_trigger = hard_test
            oracle_final = np.where(oracle_trigger, expert_preds_test, g_preds_test)

            # Trigger quality relative to the hard cases on test.
            tp = int(np.sum(trigger_test & hard_test))
            fp = int(np.sum(trigger_test & ~hard_test))
            fn = int(np.sum((~trigger_test) & hard_test))
            tn = int(np.sum((~trigger_test) & ~hard_test))
            hard_precision = tp / max(1, tp + fp)
            hard_recall = tp / max(1, tp + fn)
            false_trigger_rate = fp / max(1, fp + tn)
            missed_hard_rate = fn / max(1, fn + tp)

            # Simple accounting cost model (transparent, not a simulation of physics)
            guard_cost = 1.0
            expert_cost = 8.0
            avg_cost = guard_cost + trigger_test.mean() * expert_cost
            oracle_cost = guard_cost + oracle_trigger.mean() * expert_cost

            route_rows.append({
                "seed": seed,
                "guard": gname,
                "signal": signal_name,
                "best_threshold": chosen_t,
                "val_accuracy": float(best["system_accuracy"]),
                "val_trigger_rate": float(best["trigger_rate"]),
                "test_accuracy": accuracy_score(y_test, final_preds_test),
                "test_f1": f1_score(y_test, final_preds_test, average="binary"),
                "test_trigger_rate": float(trigger_test.mean()),
                "test_hard_precision": float(hard_precision),
                "test_hard_recall": float(hard_recall),
                "test_false_trigger_rate": float(false_trigger_rate),
                "test_missed_hard_rate": float(missed_hard_rate),
                "guard_only_accuracy": accuracy_score(y_test, g_preds_test),
                "expert_accuracy": accuracy_score(y_test, expert_preds_test),
                "oracle_accuracy": accuracy_score(y_test, oracle_final),
                "oracle_trigger_rate": float(oracle_trigger.mean()),
                "avg_cost_units": float(avg_cost),
                "oracle_cost_units": float(oracle_cost),
                "val_score": float(best["score"]),
                "test_vs_guard_gain": accuracy_score(y_test, final_preds_test) - accuracy_score(y_test, g_preds_test),
                "test_vs_expert_gap": accuracy_score(y_test, expert_preds_test) - accuracy_score(y_test, final_preds_test),
                "chosen_threshold_signal": f"{gname}:{signal_name}",
            })

        # A per-guard oracle route row (perfect hard-case routing ceiling).
        route_rows.append({
            "seed": seed,
            "guard": gname,
            "signal": "oracle_hard",
            "best_threshold": np.nan,
            "val_accuracy": np.nan,
            "val_trigger_rate": np.nan,
            "test_accuracy": accuracy_score(y_test, oracle_final),
            "test_f1": f1_score(y_test, oracle_final, average="binary"),
            "test_trigger_rate": float(hard_test.mean()),
            "test_hard_precision": 1.0,
            "test_hard_recall": 1.0,
            "test_false_trigger_rate": 0.0,
            "test_missed_hard_rate": 0.0,
            "guard_only_accuracy": accuracy_score(y_test, g_preds_test),
            "expert_accuracy": accuracy_score(y_test, expert_preds_test),
            "oracle_accuracy": accuracy_score(y_test, oracle_final),
            "oracle_trigger_rate": float(hard_test.mean()),
            "avg_cost_units": float(1.0 + hard_test.mean() * 8.0),
            "oracle_cost_units": float(1.0 + hard_test.mean() * 8.0),
            "val_score": np.nan,
            "test_vs_guard_gain": accuracy_score(y_test, oracle_final) - accuracy_score(y_test, g_preds_test),
            "test_vs_expert_gap": accuracy_score(y_test, expert_preds_test) - accuracy_score(y_test, oracle_final),
            "chosen_threshold_signal": f"{gname}:oracle_hard",
        })

        # Keep one useful detail table per guard for inspection.
        route_detail.append({
            "seed": seed,
            "guard": gname,
            "val_guard_accuracy": guard_detail[gname]["val"]["accuracy"],
            "test_guard_accuracy": guard_detail[gname]["test"]["accuracy"],
            "val_guard_ece": guard_detail[gname]["val"]["ece"],
            "test_guard_ece": guard_detail[gname]["test"]["ece"],
        })

    route_df = pd.DataFrame(route_rows)
    route_detail_df = pd.DataFrame(route_detail)
    guard_detail_df = pd.DataFrame(guard_val_rows + guard_test_rows)

    return {
        "seed": seed,
        "guards": guards,
        "expert": expert,
        "reference": reference,
        "guard_val_df": guard_val_df,
        "guard_test_df": guard_test_df,
        "route_df": route_df,
        "route_detail_df": route_detail_df,
        "guard_detail_df": guard_detail_df,
    }


def val_sum_for(detail, key):
    return detail[key]["auroc"]

# -----------------------------
# 4) Run repeated, reproducible seed stress tests
# -----------------------------
all_guard_val = []
all_guard_test = []
all_routes = []
all_route_detail = []
seed_reports = []

print("\n==================== RUNNING REPEATED SEED STRESS TESTS ====================")
for seed in SEEDS:
    print(f"\n--- Seed {seed} ---")
    # 60/20/20 split on the balanced dataset.
    X_trainval, X_test, y_trainval, y_test = train_test_split(
        X_ALL,
        Y_ALL,
        test_size=0.20,
        random_state=seed,
        stratify=Y_ALL,
    )
    X_train, X_val, y_train, y_val = train_test_split(
        X_trainval,
        y_trainval,
        test_size=0.25,
        random_state=seed + 1,
        stratify=y_trainval,
    )

    result = choose_guard_and_signal_for_seed(seed, X_train, y_train, X_val, y_val, X_test, y_test)
    all_guard_val.append(result["guard_val_df"])
    all_guard_test.append(result["guard_test_df"])
    all_routes.append(result["route_df"])
    all_route_detail.append(result["route_detail_df"])

    # A short per-seed report: best validation-derived route on test.
    seed_route = result["route_df"].copy()
    seed_route = seed_route[seed_route["signal"] != "oracle_hard"]
    best_seed = seed_route.sort_values(["test_accuracy", "test_trigger_rate"], ascending=[False, True]).iloc[0]
    seed_reports.append(best_seed.to_dict())

    print(f"Best route on test for seed {seed}: {best_seed['guard']} + {best_seed['signal']} @ t={best_seed['best_threshold']:.4f}")
    print(f"  test_accuracy={best_seed['test_accuracy']:.4f} | trigger_rate={best_seed['test_trigger_rate']:.4f} | avg_cost={best_seed['avg_cost_units']:.2f}")

# Combine all seed results
guard_val_all = pd.concat(all_guard_val, ignore_index=True)
guard_test_all = pd.concat(all_guard_test, ignore_index=True)
route_all = pd.concat(all_routes, ignore_index=True)
route_detail_all = pd.concat(all_route_detail, ignore_index=True)
seed_report_df = pd.DataFrame(seed_reports)

# -----------------------------
# 5) Guard-only leaderboard across seeds
# -----------------------------
print("\n==================== GUARD-ONLY LEADERBOARD (TEST, MEAN ± STD) ====================")
guard_leaderboard = (
    guard_test_all
    .groupby("model", as_index=False)
    .agg({
        "accuracy": ["mean", "std"],
        "macro_f1": ["mean", "std"],
        "log_loss": ["mean", "std"],
        "avg_conf": ["mean", "std"],
        "avg_conf_correct": ["mean", "std"],
        "avg_conf_wrong": ["mean", "std"],
        "ece": ["mean", "std"],
        "hard_auc_conf": ["mean", "std"],
        "hard_auc_margin": ["mean", "std"],
        "hard_auc_entropy": ["mean", "std"],
    })
)

# Flatten columns
def _flatten_columns(df):
    flat = []
    for col in df.columns:
        if isinstance(col, tuple):
            parts = [str(x) for x in col if str(x)]
            flat.append("_".join(parts).rstrip("_"))
        else:
            flat.append(str(col))
    df.columns = flat
    return df

_flatten_columns(guard_leaderboard)
print(guard_leaderboard.round(4).sort_values("accuracy_mean", ascending=False).to_string(index=False))

# -----------------------------
# 6) Full routing leaderboard across seeds
# -----------------------------
print("\n==================== ROUTING LEADERBOARD (TEST, MEAN ± STD) ====================")
route_summary = (
    route_all
    .groupby(["guard", "signal"], as_index=False)
    .agg({
        "best_threshold": ["mean", "std"],
        "test_accuracy": ["mean", "std"],
        "test_f1": ["mean", "std"],
        "test_trigger_rate": ["mean", "std"],
        "test_hard_precision": ["mean", "std"],
        "test_hard_recall": ["mean", "std"],
        "test_false_trigger_rate": ["mean", "std"],
        "test_missed_hard_rate": ["mean", "std"],
        "guard_only_accuracy": ["mean", "std"],
        "expert_accuracy": ["mean", "std"],
        "oracle_accuracy": ["mean", "std"],
        "oracle_trigger_rate": ["mean", "std"],
        "avg_cost_units": ["mean", "std"],
        "oracle_cost_units": ["mean", "std"],
        "test_vs_guard_gain": ["mean", "std"],
        "test_vs_expert_gap": ["mean", "std"],
    })
)
_flatten_columns(route_summary)
route_summary = route_summary.sort_values(["test_accuracy_mean", "test_trigger_rate_mean"], ascending=[False, True])
print(route_summary.round(4).to_string(index=False))

# -----------------------------
# 7) Best overall strategy (averaged over seeds)
# -----------------------------
best_overall = route_summary.iloc[0]
print("\n==================== BEST OVERALL AVERAGED STRATEGY ====================")
print(best_overall.to_string())

# -----------------------------
# 8) Useful diagnostics: oracle ceiling and best per-seed routes
# -----------------------------
print("\n==================== BEST ROUTE PER SEED ====================")
for _, row in seed_report_df.iterrows():
    print(
        f"seed={int(row['seed'])} | guard={row['guard']} | signal={row['signal']} | "
        f"t={row['best_threshold']:.4f} | acc={row['test_accuracy']:.4f} | "
        f"trigger={row['test_trigger_rate']:.4f} | cost={row['avg_cost_units']:.2f}"
    )

# -----------------------------
# 9) A small fairness summary
# -----------------------------
print("\n==================== FAIRNESS / INTERPRETATION SUMMARY ====================")
print(f"Balanced dataset class counts: {np.bincount(Y_ALL).tolist()}")
print(f"Seeds tested: {SEEDS}")
print(f"Cost penalty used for threshold selection: {COST_PENALTY}")
