# Plot 3: hard-case AUROC by guard signal on the test set
rep_seed = SEEDS[0]
rep = run_seed(rep_seed)
rep_guard = rep["guard_df"].iloc[0]
axes[2].bar(["conf", "margin", "entropy"], [rep_guard["hard_auc_conf"], rep_guard["hard_auc_margin"], rep_guard["hard_auc_entropy"]])
axes[2].set_title("Hard-case detection AUROC")
axes[2].set_ylim(0.0, 1.0)
