# 9) Save outputs
# -----------------------------
static_summary.to_csv(OUT_DIR / "static_summary.csv", index=False)
guard_summary.to_csv(OUT_DIR / "guard_summary.csv", index=False)
route_summary.to_csv(OUT_DIR / "route_summary.csv", index=False)
route_all.to_csv(OUT_DIR / "route_all_seed_level.csv", index=False)
guard_all.to_csv(OUT_DIR / "guard_all_seed_level.csv", index=False)
