print(f"\nSaved all reports to: {OUT_DIR}")
print("Done.")

# ==================== SIGNAL ABLATION LAB v4: MARGIN + WOBBLE ====================
# CPU-only, reproducible, one-factor-at-a-time.
#
# What changes here:
#   - margin
#   - wobble
#   - combined = margin + wobble
#
# Everything else stays fixed:
#   - same dataset
#   - same split logic
#   - same guard
#   - same experts
#   - same repeated seeds
#
# Wobble:
#   prediction stability under light perturbation
#   higher wobble = more unstable = harder case
#
# Combined signal:
#   weighted blend of margin hardness and wobble hardness

import gc
import time
import warnings
import tracemalloc
from pathlib import Path

import numpy as np
import pandas as pd
import psutil

from sklearn.base import clone
from sklearn.calibration import CalibratedClassifierCV
from sklearn.datasets import load_digits
from sklearn.dummy import DummyClassifier
from sklearn.ensemble import ExtraTreesClassifier, RandomForestClassifier
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import accuracy_score, f1_score, log_loss, roc_auc_score
from sklearn.model_selection import train_test_split
