axes[0].legend(fontsize=7)

# Plot 2: accuracy vs total wall time
for (noise_std, signal), grp in plot_df.groupby(["noise_std", "signal"]):
    axes[1].scatter(grp["total_wall_ms_per_sample_mean"], grp["test_accuracy_mean"], label=f"{signal} @ noise={noise_std:.2f}")
axes[1].set_title("Accuracy vs Total Wall Time")
axes[1].set_xlabel("Total wall ms/sample")
axes[1].set_ylabel("Test accuracy")
axes[1].grid(True, alpha=0.3)
axes[1].legend(fontsize=7)

# Plot 3: signal quality by noise
for signal, grp in signal_quality_summary.groupby("signal"):
    axes[2].plot(grp["noise_std_mean"], grp["hard_auc_mean"], marker="o", label=signal)
axes[2].set_title("Hard-case AUROC vs Wobble Noise")
axes[2].set_xlabel("Wobble noise std")
axes[2].set_ylabel("Hard-case AUROC")
axes[2].grid(True, alpha=0.3)
axes[2].legend()

