        "guard_only_accuracy",
        "expert_accuracy",
        "oracle_accuracy",
        "oracle_trigger_rate",
        "avg_cost_units",
        "oracle_cost_units",
        "test_vs_guard_gain",
        "test_vs_expert_gap",
