        "signal_wall_ms_per_sample",
        "route_wall_ms_per_sample",
        "total_wall_ms_per_sample",
        "guard_cpu_ms_per_sample",
        "signal_cpu_ms_per_sample",
        "route_cpu_ms_per_sample",
