plt.figure(figsize=(7, 5))
for sig, grp in route_summary.groupby("signal"):
    plt.scatter(grp["test_trigger_rate_mean"], grp["test_balanced_accuracy_mean"], label=sig)
plt.xlabel("Trigger rate")
plt.ylabel("Balanced accuracy")
plt.title("Rare-event routing: balanced accuracy vs trigger")
plt.grid(True, alpha=0.3)
plt.legend()
plt.tight_layout()
plt.savefig(OUT_DIR / "fraud_balanced_accuracy_vs_trigger.png", dpi=300, bbox_inches="tight")
